insert into public.exercises (workspace_id,muscle_group,equipment,translations,photo_url,video_url) values
(null,'chest','Barbell + bench', '{"ru":{"name":"Жим штанги лёжа","description":"Сведите лопатки, поставьте стопы устойчиво. Контролируйте движение штанги и положение запястий.","faq":"Не отрывайте таз от скамьи и не бросайте штангу на грудь."},"en":{"name":"Barbell bench press","description":"Retract your shoulder blades, plant your feet and lower the bar under control.","faq":"Do not bounce the bar or raise your hips."},"sr":{"name":"Potisak sa klupe","description":"Spojite lopatice, stabilizujte stopala i kontrolisano spuštajte šipku.","faq":"Ne odbijajte šipku od grudi."}}', '', ''),
(null,'legs','Barbell + rack', '{"ru":{"name":"Приседания со штангой","description":"Контролируйте положение спины, коленей и глубину приседа.","faq":"Не допускайте потери устойчивости или округления спины."},"en":{"name":"Barbell squat","description":"Maintain a stable spine and controlled squat depth.","faq":"Avoid collapsing knees or losing balance."},"sr":{"name":"Čučanj sa šipkom","description":"Držite stabilna leđa i kontrolisanu dubinu čučnja.","faq":"Izbegavajte gubitak ravnoteže."}}','',''),
(null,'back','Cable machine','{"ru":{"name":"Тяга верхнего блока","description":"Тяните рукоять к верхней части груди без рывков.","faq":"Не отклоняйтесь чрезмерно назад."},"en":{"name":"Lat pulldown","description":"Pull the handle toward your upper chest without swinging.","faq":"Avoid leaning excessively backward."},"sr":{"name":"Povlačenje na lat mašini","description":"Vucite ručku ka gornjem delu grudi bez trzaja.","faq":"Ne naginjite se previše unazad."}}','',''),
(null,'core','Mat','{"ru":{"name":"Планка","description":"Держите корпус прямым и дышите равномерно.","faq":"Не проваливайтесь в пояснице."},"en":{"name":"Plank","description":"Keep a straight body line and breathe evenly.","faq":"Avoid arching your lower back."},"sr":{"name":"Plank","description":"Držite telo pravo i dišite ravnomerno.","faq":"Ne savijajte donji deo leđa."}}','','');
